(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');const button=document.querySelector('#motion');let disabled=reduce.matches;const letters=[...document.querySelectorAll('.builder>span')];const assembly=document.querySelector('.assembly');const assemblyPin=assembly.querySelector('.assembly-pin');const assemblyScenes=[...assembly.querySelectorAll('.assembly-scene')];const assemblySteps=[...assembly.querySelectorAll('.assembly-step')];const star=document.querySelector('.kitchen-star');const system=document.querySelector('.system-visual');const progress=document.querySelector('.progress');let pending=false;const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));function paintAssembly(){const r=assembly.getBoundingClientRect();const p=clamp(-r.top/Math.max(1,r.height-assemblyPin.getBoundingClientRect().height));const stage=Math.min(2,Math.floor(p*3));const local=p*3-stage;const ease=v=>v*v*(3-2*v);const gather=ease(clamp((local-.15)/.48));const result=ease(clamp((local-.5)/.2));assembly.dataset.scene=['code','build','cook'][stage];assemblyScenes.forEach((scene,i)=>{scene.classList.toggle('is-current',i===stage);scene.style.setProperty('--scene-opacity',(stage===0?1:clamp(local/.1))*(stage===2?1:clamp((1-local)/.1)));scene.style.setProperty('--spread',1-gather);scene.style.setProperty('--gather',gather);scene.style.setProperty('--piece-scale',1-.45*gather);scene.style.setProperty('--input-opacity',1-ease(clamp((local-.45)/.2)));scene.style.setProperty('--output-opacity',result);scene.style.setProperty('--output-scale',.9+.1*result);assemblySteps[i].style.setProperty('--step-progress',clamp(p*3-i))})}function paint(){pending=false;const y=scrollY,h=innerHeight;progress.style.transform=`scaleX(${clamp(y/(document.documentElement.scrollHeight-h))})`;if(disabled)return;paintAssembly();letters.forEach((l,i)=>{const p=clamp(y/h);l.style.transform=`translateY(${p*(i%2?-32:25)}px) rotate(${p*(i-3)*1.5}deg)`});const kr=star.getBoundingClientRect();star.style.transform=`rotate(${(h-kr.top)*.06}deg)`;if(system){const sr=system.getBoundingClientRect();system.style.transform=`rotate(${clamp((sr.top/h)*6,-3,3)}deg)`}}function request(){if(!pending){pending=true;requestAnimationFrame(paint)}}function sync(){document.body.classList.toggle('no-motion',disabled);button.setAttribute('aria-pressed',String(disabled));button.textContent=disabled?'Motion off':'Motion on';document.documentElement.style.scrollBehavior=disabled?'auto':'smooth';request()}button.addEventListener('click',()=>{disabled=!disabled;sync()});reduce.addEventListener('change',e=>{disabled=e.matches;sync()});addEventListener('scroll',request,{passive:true});addEventListener('resize',request);sync()})();
